// #110daf (0f8f122dc7c514c459110daf) «iOS - חיפוש בלי תוצאות במסך «תפילות»: הכרטיס «שיעורי תורה» נשאר מוצג מתחת להודעה» — עבר QA 21.10.2026.
// מה רצוי: F-40 AC4/AC5 — без результатов только пустое состояние; поиск фильтрует все пункты, «שיעורי תורה» скрыта, когда не подходит.
// Факт 21.10: «זזזזז» → только сообщение + «ניקוי החיפוש»; «ניקוי» → весь список; «תורה» → карточка, открывает S-28; «מנ» → только «מנחה»
// (2110-0f8f122d-empty/cleared/torah.png). Находка 21.10 #8a7f1a (первый тап «ניקוי החיפוש» при клавиатуре только закрывал её) —
// исправлена, עבר QA 25.10: tapClearSearch больше не скрывает клавиатуру (обход убран; отдельная проверка — qa-2510/q-12).
// Ввод иврита — значением поля (setValue), не mobile:keys. Кейс: .qa/tests/prayer-catalog/PC-05-search-filters-lessons-card.md.
import { expect, driver } from '@wdio/globals';
import { byText, byTextContains, scrollToText } from '../../helpers/ui.ts';
import { shown } from '../_lib/app-0710.ts';
import { goHome, openCatalog, catalogSearch } from '../_lib/readiness-1910.ts';
import { typeInto, tapClearSearch, lessonsCard, catalogTitles, EMPTY_SEARCH, CLEAR_SEARCH, LESSONS_CARD } from '../_lib/app-2110.ts';

async function search(t: string) {
  const f = (await catalogSearch()) as unknown as WebdriverIO.Element;
  await typeInto(f, t);
}

describe('21.10 — поиск «תפילות» фильтрует и «שיעורי תורה» (#110daf)', () => {
  afterEach(async () => {
    if (await shown(byTextContains(CLEAR_SEARCH))) await tapClearSearch().catch(() => {});
    await goHome().catch(() => {});
  });

  it('PC-05a Без совпадений («זזזזז»): только «לא נמצאו תפילות שמתאימות ל…» и «ניקוי החיפוש», карточек нет (в т.ч. «שיעורי תורה»); очистка — весь список и «שיעורי תורה» #110daf #0f8f122d F-40 AC4 AC5 @prod-safe', async () => {
    await openCatalog();
    await search('זזזזז');
    await expect(byTextContains(EMPTY_SEARCH)).toBeExisting({ wait: 15000 });
    await expect(byTextContains('זזזזז')).toBeExisting();
    await expect(byTextContains(CLEAR_SEARCH)).toBeExisting();
    expect(await (await lessonsCard()).isExisting()).toBe(false);
    expect(await catalogTitles()).toEqual([]);

    await tapClearSearch();
    await driver.waitUntil(async () => !(await shown(byTextContains(EMPTY_SEARCH))), { timeout: 10000, timeoutMsg: 'после «ניקוי החיפוש» осталось пустое состояние' });
    await expect(byText('שחרית')).toBeExisting();
    await scrollToText(LESSONS_CARD, 12);                 // последняя карточка списка вернулась
    expect(await (await lessonsCard()).isExisting()).toBe(true);
  });

  it('PC-05b «תורה» → карточка «שיעורי תורה» видна и открывает список уроков (S-28); «מנ» → только «מנחה» #110daf #0f8f122d F-40 AC5 @prod-safe', async () => {
    await openCatalog();
    await search('תורה');
    const card = await lessonsCard();
    await card.waitForExist({ timeout: 15000 });
    expect(await shown(byTextContains(EMPTY_SEARCH))).toBe(false);
    await card.click();
    await expect(byTextContains('השיעורים מוצגים לפי סדר האלף־בית של שמם')).toBeExisting({ wait: 20000 });

    await openCatalog();
    await search('מנ');
    await driver.waitUntil(async () => (await catalogTitles()).length > 0, { timeout: 15000, timeoutMsg: 'по «מנ» нет карточек' });
    expect(await catalogTitles()).toEqual(['מנחה']);
    expect(await (await lessonsCard()).isExisting()).toBe(false);
    // Строка о нусахе остаётся над списком.
    await expect(byTextContains('התפילות מוצגות בנוסח')).toBeExisting();
  });
});
